<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';
import { adminApi,money } from '../api';
import type { AnalyticsResponse } from '../types';
const days=ref(30),loading=ref(false),error=ref(''); const data=ref<AnalyticsResponse|null>(null);let sequence=0;
const max=computed(()=>Math.max(1,...(data.value?.trend||[]).map(d=>d.paidFen)));
async function refresh(){const current=++sequence;loading.value=true;error.value='';try{const result=await adminApi.summary(days.value);if(current===sequence)data.value=result;}catch(e){if(current===sequence)error.value=e instanceof Error?e.message:'加载失败';}finally{if(current===sequence)loading.value=false;}}
onMounted(refresh);
</script>
<template><section class="page-section"><div class="page-intro"><div><h1>经营概览</h1><p v-if="data">{{data.rangeStart}} — {{data.date}}</p></div><div class="toolbar-actions"><select v-model.number="days" @change="refresh" aria-label="统计周期"><option :value="7">近 7 天</option><option :value="30">近 30 天</option><option :value="90">近 90 天</option></select><button class="soft-button" @click="refresh" :disabled="loading">{{loading?'加载中…':'刷新数据'}}</button></div></div><div v-if="error" class="field-error" role="alert">{{error}}</div><template v-if="data"><div class="metric-grid"><article class="metric-card accent"><span>净收款</span><strong>{{money(data.metrics.netFen)}}</strong><small>收款减去已到账退款</small></article><article class="metric-card"><span>完成服务</span><strong>{{data.metrics.completedCount}}</strong><small>{{money(data.metrics.completedFen)}}</small></article><article class="metric-card"><span>到店顾客</span><strong>{{data.metrics.customerCount}}</strong><small>按顾客去重</small></article><article class="metric-card"><span>客单价</span><strong>{{money(data.metrics.averageOrderFen)}}</strong><small>已支付订单平均实付</small></article></div><div class="analytics-layout"><section class="panel analytics-trend"><div class="panel-heading"><h2>收款趋势</h2><span>{{money(data.metrics.paidFen)}}</span></div><div class="trend-bars" :style="{'--days':data.trend.length}"><div v-for="(point,index) in data.trend" :key="point.date" class="trend-column" :title="`${point.date} 收款 ${money(point.paidFen)} · 完成 ${point.completedCount} 单`"><div class="trend-track"><i :style="{height:point.paidFen?`${Math.max(2,point.paidFen/max*100)}%`:'0%'}"/></div><small v-if="index===0||index===data.trend.length-1||index===Math.floor(data.trend.length/2)">{{point.date.slice(5)}}</small></div></div><p v-if="!data.metrics.paidFen" class="chart-empty">本期暂无收款</p></section><section class="panel customer-panel"><h2>新客与老客</h2><div class="customer-numbers"><div><strong>{{data.metrics.newCustomerCount}}</strong><span>新客</span></div><div><strong>{{data.metrics.returningCustomerCount}}</strong><span>老客</span></div></div><div class="customer-ratio"><i :style="{width:`${data.metrics.customerCount?100-data.metrics.repeatRate:0}%`}"/></div><div class="customer-caption"><span>老客占比</span><strong>{{data.metrics.repeatRate}}%</strong></div><p>新客为本期首次完成服务的顾客；老客在此前已有完成记录。</p></section></div><div class="analytics-rankings"><section v-for="group in [{title:'热门款式',items:data.works},{title:'项目预约',items:data.services},{title:'技师预约',items:data.technicians}]" :key="group.title" class="panel ranking-panel"><h2>{{group.title}}</h2><div v-for="(item,index) in group.items" :key="item.id" class="ranking-row"><b>{{index+1}}</b><span>{{item.name}}</span><strong>{{item.count}} 单</strong></div><p v-if="!group.items.length" class="empty-inline">暂无数据</p></section></div><div class="analytics-foot"><span>新建订单 {{data.metrics.orderCount}}</span><span>退款 {{money(data.metrics.refundFen)}}</span><span>未到店 {{data.metrics.noShowCount}}</span></div></template></section></template>
